// Obtener datos de pedidos
const pedidos = $('Get Pedidos').all();

// ===== MÉTRICAS GENERALES =====
const totalPedidos = pedidos.length;
const pedidosEntregados = pedidos.filter(p => p.json.estado === 'Entregado').length;
const pedidosEnProceso = pedidos.filter(p => ['Confirmado', 'En camino'].includes(p.json.estado)).length;
const pedidosCancelados = pedidos.filter(p => p.json.estado === 'Cancelado').length;

// Calcular valores monetarios
const valorTotalPedidos = pedidos.reduce((sum, p) => sum + (parseFloat(p.json.valor_final) || 0), 0);
const valorPromedioPedido = totalPedidos > 0 ? valorTotalPedidos / totalPedidos : 0;

// Tasa de conversión
const tasaConversion = totalPedidos > 0 ? ((pedidosEntregados / totalPedidos) * 100).toFixed(1) : 0;

// ===== PEDIDOS POR ESTADO =====
const pedidosPorEstado = pedidos.reduce((acc, p) => {
  const estado = p.json.estado;
  acc[estado] = (acc[estado] || 0) + 1;
  return acc;
}, {});

// ===== PEDIDOS POR ZONA =====
const pedidosPorZona = pedidos.reduce((acc, p) => {
  const zona = p.json.zona_domicilio;
  acc[zona] = (acc[zona] || 0) + 1;
  return acc;
}, {});

// ===== PEDIDOS POR CIUDAD =====
const pedidosPorCiudad = pedidos.reduce((acc, p) => {
  const ciudad = p.json.ciudad || 'Sin especificar';
  acc[ciudad] = (acc[ciudad] || 0) + 1;
  return acc;
}, {});

// ===== EVOLUCIÓN EN EL TIEMPO (últimos 30 días) =====
const hoy = new Date();
const diasData = [];
for (let i = 29; i >= 0; i--) {
  const fecha = new Date(hoy);
  fecha.setDate(fecha.getDate() - i);
  const fechaStr = fecha.toISOString().split('T')[0];

  const pedidosDia = pedidos.filter(p => {
    const pedidoFecha = new Date(p.json.fecha_pedido).toISOString().split('T')[0];
    return pedidoFecha === fechaStr;
  }).length;

  diasData.push({
    fecha: fechaStr,
    dia: fecha.getDate(),
    mes: fecha.getMonth() + 1,
    pedidos: pedidosDia
  });
}

// ===== MÉTRICAS POR PERÍODO =====
const fechaUnMesAtras = new Date();
fechaUnMesAtras.setMonth(fechaUnMesAtras.getMonth() - 1);
const pedidosUltimoMes = pedidos.filter(p => new Date(p.json.fecha_pedido) >= fechaUnMesAtras).length;

const fechaUnaSemanaAtras = new Date();
fechaUnaSemanaAtras.setDate(fechaUnaSemanaAtras.getDate() - 7);
const pedidosUltimaSemana = pedidos.filter(p => new Date(p.json.fecha_pedido) >= fechaUnaSemanaAtras).length;

// ===== VALOR POR ZONA =====
const valorPorZona = pedidos.reduce((acc, p) => {
  const zona = p.json.zona_domicilio;
  if (!acc[zona]) {
    acc[zona] = { total: 0, cantidad: 0 };
  }
  acc[zona].total += parseFloat(p.json.valor_final) || 0;
  acc[zona].cantidad += 1;
  return acc;
}, {});

// ===== FECHA DE ACTUALIZACIÓN =====
const fechaActualizacion = new Date().toLocaleString('es-CO', {
  timeZone: 'America/Bogota',
  year: 'numeric',
  month: 'long',
  day: 'numeric',
  hour: '2-digit',
  minute: '2-digit'
});

// ===== OBTENER LISTAS ÚNICAS PARA FILTROS =====
const zonasUnicas = [...new Set(pedidos.map(p => p.json.zona_domicilio))].sort();
const ciudadesUnicas = [...new Set(pedidos.map(p => p.json.ciudad || 'Sin especificar'))].sort();
const estadosUnicos = [...new Set(pedidos.map(p => p.json.estado))].sort();

// ===== DATOS COMPLETOS DE PEDIDOS PARA TABLA =====
const pedidosDetalle = pedidos.map(p => ({
  id: p.json.pedido_id,
  fecha: new Date(p.json.fecha_pedido).toLocaleString('es-CO', { 
    year: 'numeric', 
    month: '2-digit', 
    day: '2-digit',
    hour: '2-digit',
    minute: '2-digit'
  }),
  estado: p.json.estado,
  zona: p.json.zona_domicilio,
  ciudad: p.json.ciudad || 'N/A',
  valor: parseFloat(p.json.valor_final) || 0,
  usuario: p.json.nombre_usuario,
  domiciliario: p.json.domiciliario_asignado || 'Sin asignar'
})).sort((a, b) => b.id - a.id); // Más recientes primero

// Return all metrics
return [{
  json: {
    metricas: {
      total: totalPedidos,
      entregados: pedidosEntregados,
      enProceso: pedidosEnProceso,
      cancelados: pedidosCancelados,
      valorTotal: Math.round(valorTotalPedidos),
      valorPromedio: Math.round(valorPromedioPedido),
      tasaConversion: parseFloat(tasaConversion),
      ultimoMes: pedidosUltimoMes,
      ultimaSemana: pedidosUltimaSemana
    },
    porEstado: pedidosPorEstado,
    porZona: pedidosPorZona,
    porCiudad: pedidosPorCiudad,
    valorPorZona: valorPorZona,
    evolucion: diasData,
    filtros: {
      zonas: zonasUnicas,
      ciudades: ciudadesUnicas,
      estados: estadosUnicos
    },
    pedidosDetalle: pedidosDetalle,
    meta: {
      fechaActualizacion: fechaActualizacion
    }
  }
}];

// Obtener datos del merge (usuarios + pedidos)
const mergedData = $input.all();

console.log('Total de registros merged:', mergedData.length);

// Extraer usuarios únicos y sus pedidos
const usuariosMap = new Map();
const pedidosPorUsuario = new Map();

mergedData.forEach(item => {
  const data = item.json;
  const usuarioId = data.id; // ID del usuario
  const telefono = data.numero_telefono;

  // Agregar usuario único
  if (!usuariosMap.has(usuarioId)) {
    usuariosMap.set(usuarioId, {
      id: usuarioId,
      nombre: (data.nombre || '') + ' ' + (data.apellido || ''),
      email: data.email || 'N/A',
      telefono: telefono,
      ciudad: data.ciudad,
      zona: data.zona_domicilio,
      estado: 'Activo', // Puedes ajustar esto según tu lógica
      fechaRegistro: data.fecha_registro
    });
  }

  // Agregar pedido a la lista del usuario (solo si existe pedido_id)
  if (data.pedido_id) {
    if (!pedidosPorUsuario.has(usuarioId)) {
      pedidosPorUsuario.set(usuarioId, []);
    }

    pedidosPorUsuario.get(usuarioId).push({
      pedidoId: data.pedido_id,
      fecha: data.fecha_pedido,
      valor: parseFloat(data.valor_final) || 0,
      estado: data.estado
    });
  }
});

const usuarios = Array.from(usuariosMap.values());
console.log('Usuarios únicos:', usuarios.length);

// ===== MÉTRICAS GENERALES =====
const totalUsuarios = usuarios.length;

// Contar usuarios activos (con pedidos en los últimos 30 días)
const hace30Dias = new Date();
hace30Dias.setDate(hace30Dias.getDate() - 30);

const usuariosActivos = usuarios.filter(u => {
  const pedidos = pedidosPorUsuario.get(u.id) || [];
  return pedidos.some(p => new Date(p.fecha) >= hace30Dias);
}).length;

// ===== CALCULAR MÉTRICAS POR USUARIO =====
const usuariosConMetricas = usuarios.map(u => {
  const pedidos = pedidosPorUsuario.get(u.id) || [];
  const totalPedidos = pedidos.length;
  const valorTotal = pedidos.reduce((sum, p) => sum + p.valor, 0);

  // Última actividad basada en último pedido
  let ultimaActividad;
  if (pedidos.length > 0) {
    const fechasPedidos = pedidos
      .map(p => new Date(p.fecha))
      .filter(f => !isNaN(f.getTime())); // Filtrar fechas inválidas

    ultimaActividad = fechasPedidos.length > 0 
      ? new Date(Math.max(...fechasPedidos))
      : new Date(u.fechaRegistro);
  } else {
    ultimaActividad = new Date(u.fechaRegistro);
  }

  return {
    ...u,
    pedidosRealizados: totalPedidos,
    valorTotal: valorTotal,
    valorPromedio: totalPedidos > 0 ? valorTotal / totalPedidos : 0,
    ultimaActividad: ultimaActividad
  };
});

// Ordenar por ID descendente
usuariosConMetricas.sort((a, b) => {
  const idA = String(a.id);
  const idB = String(b.id);
  return idB.localeCompare(idA);
});

// ===== MÉTRICAS AGREGADAS =====
const totalPedidosRealizados = usuariosConMetricas.reduce((sum, u) => sum + u.pedidosRealizados, 0);
const valorTotalGenerado = usuariosConMetricas.reduce((sum, u) => sum + u.valorTotal, 0);
const pedidosPromedioPorUsuario = totalUsuarios > 0 ? (totalPedidosRealizados / totalUsuarios).toFixed(1) : 0;
const valorPromedioPorUsuario = totalUsuarios > 0 ? valorTotalGenerado / totalUsuarios : 0;

// ===== USUARIOS POR ESTADO =====
const usuariosPorEstado = usuariosConMetricas.reduce((acc, u) => {
  const estado = u.estado || 'Activo';
  acc[estado] = (acc[estado] || 0) + 1;
  return acc;
}, {});

// ===== USUARIOS POR CIUDAD =====
const usuariosPorCiudad = usuariosConMetricas.reduce((acc, u) => {
  const ciudad = u.ciudad || 'Sin especificar';
  acc[ciudad] = (acc[ciudad] || 0) + 1;
  return acc;
}, {});

// ===== USUARIOS POR ZONA =====
const usuariosPorZona = usuariosConMetricas.reduce((acc, u) => {
  const zona = u.zona || 'Sin especificar';
  acc[zona] = (acc[zona] || 0) + 1;
  return acc;
}, {});

// ===== EVOLUCIÓN DE REGISTROS (últimos 30 días) =====
const hoy = new Date();
const diasData = [];
for (let i = 29; i >= 0; i--) {
  const fecha = new Date(hoy);
  fecha.setDate(fecha.getDate() - i);
  const fechaStr = fecha.toISOString().split('T')[0];

  const registrosDia = usuariosConMetricas.filter(u => {
    try {
      const fechaRegistro = new Date(u.fechaRegistro);
      if (isNaN(fechaRegistro.getTime())) return false;
      return fechaRegistro.toISOString().split('T')[0] === fechaStr;
    } catch (e) {
      return false;
    }
  }).length;

  diasData.push({
    fecha: fechaStr,
    dia: fecha.getDate(),
    mes: fecha.getMonth() + 1,
    registros: registrosDia
  });
}

// ===== MÉTRICAS POR PERÍODO =====
const fechaUnMesAtras = new Date();
fechaUnMesAtras.setMonth(fechaUnMesAtras.getMonth() - 1);
const usuariosUltimoMes = usuariosConMetricas.filter(u => {
  try {
    const fechaRegistro = new Date(u.fechaRegistro);
    return !isNaN(fechaRegistro.getTime()) && fechaRegistro >= fechaUnMesAtras;
  } catch (e) {
    return false;
  }
}).length;

const fechaUnaSemanaAtras = new Date();
fechaUnaSemanaAtras.setDate(fechaUnaSemanaAtras.getDate() - 7);
const usuariosUltimaSemana = usuariosConMetricas.filter(u => {
  try {
    const fechaRegistro = new Date(u.fechaRegistro);
    return !isNaN(fechaRegistro.getTime()) && fechaRegistro >= fechaUnaSemanaAtras;
  } catch (e) {
    return false;
  }
}).length;

// ===== DISTRIBUCIÓN HORARIA DE PEDIDOS =====
const actividadPorHora = new Array(24).fill(0);
mergedData.forEach(item => {
  if (item.json.fecha_pedido) {
    try {
      const fecha = new Date(item.json.fecha_pedido);
      if (!isNaN(fecha.getTime())) {
        const hora = fecha.getHours();
        if (hora >= 0 && hora < 24) {
          actividadPorHora[hora]++;
        }
      }
    } catch (e) {
      // Ignorar fechas inválidas
    }
  }
});

// ===== TOP 10 USUARIOS POR PEDIDOS =====
const topUsuariosPorPedidos = [...usuariosConMetricas]
  .filter(u => u.pedidosRealizados > 0)
  .sort((a, b) => b.pedidosRealizados - a.pedidosRealizados)
  .slice(0, 10)
  .map(u => ({
    nombre: u.nombre,
    pedidos: u.pedidosRealizados
  }));

// ===== TOP 10 USUARIOS POR VALOR =====
const topUsuariosPorValor = [...usuariosConMetricas]
  .filter(u => u.valorTotal > 0)
  .sort((a, b) => b.valorTotal - a.valorTotal)
  .slice(0, 10)
  .map(u => ({
    nombre: u.nombre,
    valor: u.valorTotal
  }));

// ===== FECHA DE ACTUALIZACIÓN =====
const fechaActualizacion = new Date().toLocaleString('es-CO', {
  timeZone: 'America/Bogota',
  year: 'numeric',
  month: 'long',
  day: 'numeric',
  hour: '2-digit',
  minute: '2-digit'
});

// ===== OBTENER LISTAS ÚNICAS PARA FILTROS =====
const zonasUnicas = [...new Set(usuariosConMetricas.map(u => u.zona || 'Sin especificar'))].sort();
const ciudadesUnicas = [...new Set(usuariosConMetricas.map(u => u.ciudad || 'Sin especificar'))].sort();
const estadosUnicos = [...new Set(usuariosConMetricas.map(u => u.estado || 'Activo'))].sort();

// ===== DATOS COMPLETOS DE USUARIOS PARA TABLA =====
const usuariosDetalle = usuariosConMetricas.map(u => {
  // Formatear fecha de registro de forma segura
  let fechaRegistroFormateada = 'N/A';
  try {
    const fechaReg = new Date(u.fechaRegistro);
    if (!isNaN(fechaReg.getTime())) {
      fechaRegistroFormateada = fechaReg.toLocaleString('es-CO', { 
        year: 'numeric', 
        month: '2-digit', 
        day: '2-digit',
        hour: '2-digit',
        minute: '2-digit'
      });
    }
  } catch (e) {
    fechaRegistroFormateada = 'N/A';
  }

  // Formatear última actividad de forma segura
  let ultimaActividadFormateada = 'N/A';
  try {
    const fechaAct = new Date(u.ultimaActividad);
    if (!isNaN(fechaAct.getTime())) {
      ultimaActividadFormateada = fechaAct.toLocaleString('es-CO', { 
        year: 'numeric', 
        month: '2-digit', 
        day: '2-digit',
        hour: '2-digit',
        minute: '2-digit'
      });
    }
  } catch (e) {
    ultimaActividadFormateada = 'N/A';
  }

  // Obtener todos los pedidos del usuario con sus fechas
  const pedidos = pedidosPorUsuario.get(u.id) || [];

  return {
    id: u.id,
    nombre: u.nombre.trim(),
    email: u.email || 'N/A',
    telefono: u.telefono || 'N/A',
    ciudad: u.ciudad || 'N/A',
    zona: u.zona || 'N/A',
    fechaRegistro: fechaRegistroFormateada,
    estado: u.estado || 'Activo',
    pedidosRealizados: u.pedidosRealizados,
    valorTotal: u.valorTotal,
    valorPromedio: Math.round(u.valorPromedio),
    ultimaActividad: ultimaActividadFormateada,
    pedidos: pedidos // Incluir todos los pedidos con fechas
  };
});

// Return all metrics
return [{
  json: {
    metricas: {
      total: totalUsuarios,
      activos: usuariosActivos,
      nuevosUltimoMes: usuariosUltimoMes,
      nuevosUltimaSemana: usuariosUltimaSemana,
      pedidosPromedio: parseFloat(pedidosPromedioPorUsuario),
      valorTotal: Math.round(valorTotalGenerado),
      valorPromedio: Math.round(valorPromedioPorUsuario),
      totalPedidos: totalPedidosRealizados
    },
    porEstado: usuariosPorEstado,
    porCiudad: usuariosPorCiudad,
    porZona: usuariosPorZona,
    evolucion: diasData,
    actividadPorHora: actividadPorHora,
    topUsuariosPorPedidos: topUsuariosPorPedidos,
    topUsuariosPorValor: topUsuariosPorValor,
    filtros: {
      zonas: zonasUnicas,
      ciudades: ciudadesUnicas,
      estados: estadosUnicos
    },
    usuariosDetalle: usuariosDetalle,
    meta: {
      fechaActualizacion: fechaActualizacion,
      totalRegistrosMerged: mergedData.length,
      usuariosUnicos: usuarios.length
    }
  }
}];
